// Package logs provides the read-only tail behind the Log page.
//
// Log sources are whitelisted keys, never user-supplied paths, so there is no
// traversal surface. In addition to the file-backed sources it can read the
// systemd journal of the local service. The structured activity stream is
// generated by the API from the events table and passed through FromLines.
package logs

import (
	"bufio"
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// Source is one selectable log in the UI.
type Source struct {
	Key       string `json:"key"`
	Label     string `json:"label"`
	Available bool   `json:"available"`
	Hint      string `json:"hint,omitempty"`
}

// Tail is the response shape of GET /api/v1/logs.
type Tail struct {
	File       string   `json:"file"`
	Label      string   `json:"label"`
	Tail       int      `json:"tail"`
	Lines      []string `json:"lines"`
	TotalBytes int64    `json:"total_bytes"`
	Mtime      *float64 `json:"mtime"`
	Hint       string   `json:"hint,omitempty"`
	Kind       string   `json:"kind"`
}

var fileSources = []struct{ key, label, name string }{
	{"agent", "agent.log", "agent.log"},
	{"errors", "errors.log", "errors.log"},
	{"gateway", "gateway.log", "gateway.log"},
	{"gui", "gui.log", "gui.log"},
	{"mcp", "mcp-stderr.log", "mcp-stderr.log"},
	{"update", "update.log", "update.log"},
}

const maxBytes = 4 << 20

func logDir() string {
	if p := strings.TrimSpace(os.Getenv("SWITCHYARD_LOG_DIR")); p != "" {
		return p
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".hermes", "logs")
}

// NormalizeTail clamps the requested number of lines.
func NormalizeTail(n int) int {
	switch {
	case n <= 0:
		return 200
	case n > 1000:
		return 1000
	default:
		return n
	}
}

// Sources lists every log the page can show. The activity stream is always
// available because it comes from the database.
func Sources() []Source {
	out := []Source{{Key: "activity", Label: "Live Activity Stream", Available: true, Hint: "Structured task events from the database"}}
	dir := logDir()
	for _, s := range fileSources {
		p := filepath.Join(dir, s.name)
		st, err := os.Stat(p)
		out = append(out, Source{Key: s.key, Label: s.label, Available: err == nil && !st.IsDir()})
	}
	if _, err := exec.LookPath("journalctl"); err == nil {
		out = append(out, Source{Key: "service", Label: "switchyard-lite.service", Available: true})
	} else {
		out = append(out, Source{Key: "service", Label: "switchyard-lite.service", Available: false, Hint: "journalctl is not available on this host"})
	}
	return out
}

// Read tails a whitelisted source and applies a case-insensitive filter.
func Read(key, query string, tail int) (Tail, error) {
	tail = NormalizeTail(tail)
	if key == "activity" {
		return Tail{}, fmt.Errorf("activity is produced from database events")
	}
	if key == "service" {
		return readService(query, tail)
	}
	for _, s := range fileSources {
		if s.key != key {
			continue
		}
		dir := logDir()
		if dir == "" {
			return Tail{}, fmt.Errorf("log directory is not configured")
		}
		lines, size, mtime, err := readFile(filepath.Join(dir, s.name))
		t := Tail{File: key, Label: s.label, Tail: tail, Lines: filter(lines, query, tail),
			TotalBytes: size, Mtime: mtime, Kind: "file"}
		if err != nil {
			t.Hint = "Log file not found yet: " + s.name
			return t, nil
		}
		return t, nil
	}
	return Tail{}, fmt.Errorf("unknown log source")
}

func readService(query string, tail int) (Tail, error) {
	t := Tail{File: "service", Label: "switchyard-lite.service", Tail: tail, Lines: []string{}, Kind: "journal"}
	if _, err := exec.LookPath("journalctl"); err != nil {
		t.Hint = "journalctl is not available on this host."
		return t, nil
	}
	ctx, cancel := context.WithTimeout(context.Background(), 4*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, "journalctl", "-u", "switchyard-lite.service", "-n", fmt.Sprint(tail), "--no-pager", "--output=short-iso")
	b, err := cmd.CombinedOutput()
	if err != nil && len(b) == 0 {
		t.Hint = "Could not read the service journal: " + firstLine(err.Error())
		return t, nil
	}
	lines := strings.Split(strings.TrimRight(string(b), "\n"), "\n")
	t.TotalBytes = int64(len(b))
	t.Lines = filter(lines, query, tail)
	if len(t.Lines) == 0 {
		t.Hint = "No service journal entries yet."
	}
	return t, nil
}

func readFile(p string) (lines []string, size int64, mtime *float64, err error) {
	st, err := os.Stat(p)
	if err != nil || st.IsDir() {
		return []string{}, 0, nil, fmt.Errorf("not found")
	}
	size = st.Size()
	mt := float64(st.ModTime().UnixNano()) / 1e9
	mtime = &mt
	f, err := os.Open(p)
	if err != nil {
		return []string{}, size, mtime, err
	}
	defer f.Close()
	if size > maxBytes {
		_, _ = f.Seek(-maxBytes, 2)
	}
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64<<10), 1<<20)
	for sc.Scan() {
		lines = append(lines, sc.Text())
	}
	return lines, size, mtime, nil
}

func filter(lines []string, query string, tail int) []string {
	q := strings.ToLower(strings.TrimSpace(query))
	out := make([]string, 0, len(lines))
	for _, l := range lines {
		if q != "" && !strings.Contains(strings.ToLower(l), q) {
			continue
		}
		out = append(out, l)
	}
	if len(out) > tail {
		out = out[len(out)-tail:]
	}
	if out == nil {
		out = []string{}
	}
	return out
}

// FromLines wraps already-formatted activity lines in the same response shape.
func FromLines(lines []string, query string, tail int) Tail {
	return Tail{
		File: "activity", Label: "Live Activity Stream", Tail: NormalizeTail(tail),
		Lines: filter(lines, query, tail), Kind: "activity",
		Hint: "Recent task, dispatch and review events from the database.",
	}
}

func firstLine(s string) string { return strings.TrimSpace(strings.SplitN(s, "\n", 2)[0]) }
